<?php require_once 'config/config.php'; require_room(); $rid=room_id();$uid=user()['id'];$st=db()->prepare("SELECT * FROM rooms WHERE id=?");$st->execute([$rid]);$room=$st->fetch();$times=$room['meal_times']==3?['breakfast','lunch','dinner']:['lunch','dinner'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['meal_date']??date('Y-m-d');if($date<date('Y-m-d',strtotime('+1 day'))){flash('Meals can be changed for tomorrow or later.');redirect('meals.php');}foreach($times as $t){$on=isset($_POST['meal_'.$t])?1:0;$q=db()->prepare("INSERT INTO meals(room_id,user_id,meal_date,meal_type,status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)");$q->execute([$rid,$uid,$date,$t,$on?'on':'off']);}flash('Meal plan updated for '.e($date));redirect('meals.php');}
$from=date('Y-m-d');$to=date('Y-m-d',strtotime('+14 days'));$q=db()->prepare("SELECT * FROM meals WHERE room_id=? AND user_id=? AND meal_date BETWEEN ? AND ? ORDER BY meal_date,meal_type");$q->execute([$rid,$uid,$from,$to]);$plans=[];foreach($q as $r)$plans[$r['meal_date']][$r['meal_type']]=$r['status'];
$title='Meals';include 'includes/header.php';?><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="fw-bold">Meal planner</h2><p class="small-muted mb-0">Turn meals on/off at least one day before eating.</p></div><?php if(room_role()==='chef'):?><span class="badge badge-soft">Chef view enabled</span><?php endif;?></div>
<div class="card p-4 mb-4"><form method="post" class="row g-3 align-items-end"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="col-md-4"><label class="form-label">Date</label><input type="date" class="form-control" name="meal_date" min="<?=date('Y-m-d',strtotime('+1 day'))?>" value="<?=date('Y-m-d',strtotime('+1 day'))?>"></div><?php foreach($times as $t):?><div class="col-md-2"><div class="form-check form-switch mt-4"><input class="form-check-input" type="checkbox" name="meal_<?=$t?>" id="<?=$t?>" checked><label class="form-check-label text-capitalize" for="<?=$t?>"><?=e($t)?></label></div></div><?php endforeach;?><div class="col-md-4"><button class="btn btn-dark">Save meal plan</button></div></form></div>
<div class="card p-4"><h5 class="fw-bold">Next 14 days</h5><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><?php foreach($times as $t):?><th class="text-capitalize"><?=$t?></th><?php endforeach;?><th>Total</th></tr></thead><tbody><?php for($i=0;$i<14;$i++):$d=date('Y-m-d',strtotime("+$i day"));$c=0;?><tr><td><?=date('D, d M',strtotime($d))?></td><?php foreach($times as $t):$s=$plans[$d][$t]??'on';$c+=($s==='on');?><td><span class="badge <?=$s==='on'?'text-bg-success':'text-bg-secondary'?>"><?=$s?></span></td><?php endforeach;?><td><b><?=$c?></b></td></tr><?php endfor;?></tbody></table></div></div><?php include 'includes/footer.php';?>